type ComponentKind = 'english' | 'life-project';
type Orientation = 'portrait' | 'landscape';
type FloatingType = 'image' | 'textbox';
type PdfMode = 'activity' | 'activity-key' | 'key';

type ImageAdjustments = {left:number;top:number;right:number;bottom:number;rotation:number;brightness:number;contrast:number;gray:boolean};
type FloatingObject = {
  id: string;
  pageId: string;
  type: FloatingType;
  x: number;
  y: number;
  width: number;
  height: number;
  src?: string;
  originalSrc?: string;
  imageAdjustments?: ImageAdjustments;
  lockRatio?: boolean;
  html?: string;
  border?: boolean;
  z: number;
  anchorId?: string;
};

type PageBorder = {width:number;style:"solid"|"double"|"dashed"|"dotted";color:string;gap:number};
function normalizeBorder(raw:unknown):PageBorder|undefined{if(!raw||typeof raw!=="object")return undefined;const b=raw as Partial<PageBorder>;return {width:Math.max(.25,Math.min(6,Number(b.width)||1)),style:["solid","double","dashed","dotted"].includes(String(b.style))?b.style!:"solid",color:/^#[0-9a-f]{6}$/i.test(String(b.color))?b.color!:"#222222",gap:Math.max(0,Math.min(8,Number.isFinite(Number(b.gap))?Number(b.gap):2))};}
type PageData = {
  autoFlow?: boolean;
  border?: PageBorder;
  id: string;
  html: string;
  orientation: Orientation;
  columns: 1 | 2 | 3;
};

type Margins = { top: number; right: number; bottom: number; left: number };

type Activity = {
  id: string;
  component: ComponentKind;
  school: string;
  teacher: string;
  subject: string;
  grade: string;
  title: string;
  libraryName?: string;
  headerStyles?: Partial<Record<HeaderField,string>>;
  logoDataUrl?: string;
  personalLogoDataUrl?: string;
  showPersonalLogo: boolean;
  showPageNumbers: boolean;
  sourceName?: string;
  collection?: "activity" | "reference" | "both";
  originalLayout?: boolean;
  manualPagination?: boolean;
  tags?: string[];
  margins: Margins;
  pages: PageData[];
  objects: FloatingObject[];
  answerKeyHtml: string;
  questionLinks?: Record<string,{curriculumIds?:string[];curriculumObjects?:string[];name:string;skill:string;topic:string;answer:string;commented:string;numbered:boolean;number:number;includeKey:boolean}>;
  keyMode?: 'simple'|'commented'|'manual';
  createdAt: string;
  updatedAt: string;
  // compatibilidade V1/V2/V3
  content?: string;
};

type HeaderField = 'school'|'title';
type HistoryItem = { id: string; savedAt: string; activity: Activity };
type ImageBankItem = { id: string; name: string; dataUrl: string; createdAt: string };

type ImportCandidate = {
  sourceName: string;
  warning?: string;
  pages: Array<{ html: string; orientation: Orientation; columns?: 1 | 2 | 3 }>;
};

