  const blocked=new Set('SCRIPT STYLE IFRAME OBJECT EMBED FORM INPUT BUTTON TEXTAREA SELECT META LINK BASE SVG MATH VIDEO AUDIO SOURCE TEMPLATE NOSCRIPT HEAD'.split(' '));
  const structural=['font-weight','font-style','text-decoration','text-decoration-line','vertical-align','list-style-type','list-style-position','white-space'];
  const originalStyles=['font-family','font-size','line-height','margin-top','margin-bottom','margin-left','margin-right','padding-top','padding-bottom','padding-left','padding-right','text-indent','text-align','color','background-color','width','height','border','border-top','border-right','border-bottom','border-left','border-collapse','font-weight','font-style','text-decoration','text-decoration-line','vertical-align','list-style-type','list-style-position','white-space'];
