    if(node.nodeType===Node.TEXT_NODE){parent.appendChild(document.createTextNode(node.textContent||''));return;}
    if(!(node instanceof HTMLElement))return;
    const tag=node.tagName.toUpperCase(); if(blocked.has(tag))return;
    if(!allowed.has(tag)){Array.from(node.childNodes).forEach(n=>copy(n,parent));return;}
    const el=document.createElement(tag==='FONT'?'span':tag.toLowerCase());
    const styles=mode==='original'?originalStyles:structural;
    for(const k of styles){const v=node.style.getPropertyValue(k);if(v&&!/url\s*\(|expression\s*\(|javascript:|var\s*\(/i.test(v))el.style.setProperty(k,v);}
    // Word/Docs/ChatGPT typically encode emphasis in semantic tags or inline CSS.
    if(mode==='original'&&tag==='FONT'){if(node.getAttribute('face'))el.style.fontFamily=node.getAttribute('face')!;const sizes=['','8pt','10pt','12pt','14pt','18pt','24pt','36pt'];const sz=Number(node.getAttribute('size'));if(sizes[sz])el.style.fontSize=sizes[sz];if(node.getAttribute('color'))el.style.color=node.getAttribute('color')!;}
    if(mode==='original'&&['left','right','center','justify'].includes(node.getAttribute('align')||''))el.style.textAlign=node.getAttribute('align')!;
    for(const k of ['colspan','rowspan','span','start','value','width','height']){const v=node.getAttribute(k);if(v&&/^\d{1,5}%?$/.test(v))el.setAttribute(k,v);}
    if(tag==='OL'){const t=node.getAttribute('type');if(t&&/^[1aAiI]$/.test(t))el.setAttribute('type',t);if(node.hasAttribute('reversed'))el.setAttribute('reversed','');}
    if(tag==='IMG'){const src=node.getAttribute('src')||'';if(!/^(https?:\/\/|data:image\/(?:png|jpe?g|gif|webp|bmp);base64,)/i.test(src))return;el.setAttribute('src',src);el.setAttribute('alt',node.getAttribute('alt')||'Imagem colada');el.style.maxWidth='100%';el.style.height='auto';}
    if(tag==='A'){const href=node.getAttribute('href')||'';if(/^(https?:\/\/|mailto:|#)/i.test(href)){el.setAttribute('href',href);el.setAttribute('rel','noopener noreferrer');}}
