function saveLocal(){refreshLinkedKey();activity.updatedAt=nowIso();activity.content=activity.pages.map(p=>p.html).join('<hr class="soft-break">');try{dataStorage.setItem(STORAGE_KEY,compactJson(activity));if(activity.libraryName||getLibrary().some(i=>i.id===activity.id)){upsertLocalLibrary(activity);markPending(activity.id,true);}return true;}catch{status.textContent='Armazenamento local cheio';toast('Armazenamento local cheio. Não feche antes de sincronizar.');return false;}}
const persist = async () => {window.clearTimeout(saveTimer);saveTimer=undefined;dirty=false;let localOk=saveLocal();const snapshot=structuredClone(activity);const inLibrary=getLibrary().some(i=>i.id===snapshot.id);if(localOk)localOk=await flushStorage();if(!dirty&&activity.id===snapshot.id&&activity.updatedAt===snapshot.updatedAt){status.textContent=localOk?'Salvo localmente':'Aguardando nuvem';status.className='status saved';}if(navigator.onLine&&inLibrary&&!deletedIds().includes(snapshot.id)){remoteQueue=remoteQueue.catch(()=>{}).then(async()=>{const ok=await saveRemote(snapshot);if(ok){const latest=getLibrary().find(i=>i.id===snapshot.id);if(!latest||latest.updatedAt<=snapshot.updatedAt)markPending(snapshot.id,false);}if(!dirty&&activity.id===snapshot.id&&activity.updatedAt===snapshot.updatedAt){status.textContent=ok?'Sincronizado':localOk?'Salvo localmente — nuvem pendente':'Falha ao salvar';status.className=ok?'status synced':'status saved';}});await remoteQueue;}renderPreview();};
