$('toggleRuler').addEventListener('click',()=>{const el=document.querySelector<HTMLElement>('.ruler-shell')!;el.hidden=!el.hidden;dataStorage.setItem('mcs-ruler-hidden',String(el.hidden));if(!el.hidden)updateRulerHandles();});
