const pageToCanvas=async(el:HTMLElement)=>{el.classList.add('exporting','export-page');try{return await html2canvas(el,{scale:2,useCORS:true,backgroundColor:'#ffffff'});}finally{el.classList.remove('exporting','export-page');}};
const buildAnswerKeyPage=(source:Activity=activity)=>{const page=document.createElement('section');page.className='page portrait answer-key-page';page.style.setProperty('--page-width','210mm');page.style.setProperty('--page-height','297mm');page.style.setProperty('--page-margin-top','16mm');page.style.setProperty('--page-margin-right','16mm');page.style.setProperty('--page-margin-bottom','18mm');page.style.setProperty('--page-margin-left','16mm');page.innerHTML=`<div class="page-flow"><div class="key-title">GABARITO — ${escapeHtml(source.libraryName||source.title)}</div><div class="key-meta">${escapeHtml(source.subject)} • ${escapeHtml(source.grade)}</div><div class="key-content">${source.answerKeyHtml ? sanitizeImportedHtml(source.answerKeyHtml) : '<p>Gabarito ainda não preenchido.</p>'}</div></div>`;document.body.appendChild(page);return page;};
const makePdfBlob=async(mode:PdfMode='activity',source:Activity=activity)=>{refreshLinkedKey(source);if(mode!=='key'&&!activity.originalLayout&&activity.pages.length)rebalanceOverflow(activity.pages[0].id,false);const sourcePages=[...pagesMount.querySelectorAll<HTMLElement>('.page')];if(mode!=='key'&&sourcePages.some(p=>{const ed=p.querySelector<HTMLElement>('.editor');return !!ed&&(ed.scrollHeight>ed.clientHeight+4||ed.scrollWidth>ed.clientWidth+4);})&&!confirm('Há conteúdo além do limite de alguma página. O PDF pode cortá-lo. Exportar assim mesmo?'))throw new Error('Exportação cancelada. Ajuste as páginas.');const targets:HTMLElement[]=[];const keyPages:HTMLElement[]=[];if(mode!=='key')targets.push(...sourcePages);if(mode!=='activity'){const first=buildAnswerKeyPage(source);keyPages.push(first);let curr=first;const content=first.querySelector<HTMLElement>('.key-content')!;const entries=[...content.children];content.replaceChildren();for(const entry of entries){let box=curr.querySelector<HTMLElement>('.key-content')!;box.append(entry);const flow=curr.querySelector<HTMLElement>('.page-flow')!;if(flow.scrollHeight>flow.clientHeight+3&&box.childElementCount>1){entry.remove();curr=buildAnswerKeyPage(source);keyPages.push(curr);box=curr.querySelector<HTMLElement>('.key-content')!;box.replaceChildren(entry);}}targets.push(...keyPages);}if(!targets.length)throw new Error('Nenhuma página para exportar.');let pdf:jsPDF|null=null;for(let i=0;i<targets.length;i++){const el=targets[i];const orientation:Orientation=el.classList.contains('landscape')?'landscape':'portrait';const dims=pageDims(orientation);const canvas=await pageToCanvas(el);const data=canvas.toDataURL('image/jpeg',0.97);if(!pdf)pdf=new jsPDF(orientation==='landscape'?'l':'p','mm','a4');else pdf.addPage('a4',orientation==='landscape'?'l':'p');pdf.addImage(data,'JPEG',0,0,dims.width,dims.height);}keyPages.forEach(p=>p.remove());return pdf!.output('blob');};
const downloadBlob=(blob:Blob,filename:string)=>{const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1200);};
$('pdfMenuBtn').addEventListener('click',()=>showDialog('pdfDialog'));
document.querySelectorAll<HTMLButtonElement>('[data-pdf-mode]').forEach(btn=>btn.addEventListener('click',async()=>{const mode=btn.dataset.pdfMode as PdfMode;closeDialog('pdfDialog');toast('Gerando PDF…');try{const blob=await makePdfBlob(mode);const suffix=mode==='activity'?'':mode==='key'?' - Gabarito':' - Com Gabarito';downloadBlob(blob,`${activity.libraryName||activity.title||'atividade'}${suffix}.pdf`);toast('PDF gerado.');}catch(e){toast(e instanceof Error?e.message:'Falha ao gerar PDF.');}}));
const shareDialog=document.createElement('dialog');shareDialog.className='modal small-modal';shareDialog.innerHTML='<div class="modal-head"><strong>Compartilhar PDF</strong><button id="closeShare" aria-label="Fechar">✕</button></div><p id="shareMessage">Preparando arquivo…</p><div class="modal-actions"><button id="shareNative" hidden>Enviar arquivo pelo celular</button><button id="shareWA" disabled>Baixar PDF e abrir WhatsApp</button></div>';document.body.appendChild(shareDialog);let shareFile:File|null=null;
$('closeShare').onclick=()=>shareDialog.close();$('shareWA').onclick=()=>{if(!shareFile)return;window.open('https://wa.me/?text='+encodeURIComponent('Segue a atividade: '+shareFile.name),'_blank','noopener,noreferrer');downloadBlob(shareFile,shareFile.name);$('shareMessage').textContent='Escolha o contato no WhatsApp e anexe o PDF baixado pelo clipe. Nenhum documento foi publicado em link público.';};
