function openSaveDialog(mode:'save'|'copy'|'rename') {saveMode=mode;$('saveDialogTitle').textContent=mode==='copy'?'Salvar como — nova cópia':mode==='rename'?'Renomear atividade':'Salvar atividade';$<HTMLInputElement>('saveName').value=activityName(activity)+(mode==='copy'?' — Cópia':'');$<HTMLSelectElement>('saveComponent').value=activity.component;$<HTMLInputElement>('saveGrade').value=activity.grade;showDialog('saveDialog');}
$('fileSave').addEventListener('click',()=>{if(!activity.libraryName||activity.collection==='reference')openSaveDialog('save');else{void persist();toast('Atividade atualizada em Minhas Atividades. Confira o status.');}});
$('fileSaveAs').addEventListener('click',()=>openSaveDialog('copy'));$('fileRename').addEventListener('click',()=>openSaveDialog('rename'));
$('saveForm').addEventListener('submit',async e=>{e.preventDefault();const name=$<HTMLInputElement>('saveName').value.trim();if(!name)return;const button=$<HTMLButtonElement>('saveConfirm');button.disabled=true;try{if(saveMode==='copy'){await persist();activity=cloneDocument(activity,activity.title);activePageId=activity.pages[0].id;selectedObjectId=null;}activity.libraryName=name;const component=$<HTMLSelectElement>('saveComponent').value as ComponentKind;if(component!==activity.component){activity.component=component;activity.subject=profileDefaults[component].subject;}activity.grade=$<HTMLInputElement>('saveGrade').value.trim();if(activity.collection==='reference')activity.collection='both';render();recordEdit();if(!saveLocal()){toast('Não foi possível salvar localmente.');return;}closeDialog('saveDialog');void persist();toast(saveMode==='copy'?'Cópia criada em Minhas Atividades.':'Salvo em Minhas Atividades.');}finally{button.disabled=false;}});


// Modelos + layouts pessoais em localStorage
const LAYOUT_MODELS_KEY='marks-class-studio:layout-models:v4';
type LayoutModel={id:string;name:string;component:ComponentKind;orientation:Orientation;columns:1|2|3;pageCount:number;margins:Margins;showPageNumbers:boolean;showPersonalLogo:boolean};
const baseModels=[
  {name:'Inglês — Atividade 1 página',component:'english' as ComponentKind,orientation:'portrait' as Orientation,columns:1 as const,pageCount:1},
  {name:'Inglês — 2 páginas / 2 colunas',component:'english' as ComponentKind,orientation:'portrait' as Orientation,columns:2 as const,pageCount:2},
  {name:'Projeto de Vida — Reflexão 2 páginas',component:'life-project' as ComponentKind,orientation:'portrait' as Orientation,columns:1 as const,pageCount:2},
  {name:'Paisagem — atividade ampla',component:'english' as ComponentKind,orientation:'landscape' as Orientation,columns:2 as const,pageCount:1}
];
const getLayoutModels=():LayoutModel[]=>safeJson(dataStorage.getItem(LAYOUT_MODELS_KEY),[]);
const applyLayoutModel=(m:Pick<LayoutModel,'component'|'orientation'|'columns'|'pageCount'> & Partial<LayoutModel>)=>{activity.component=m.component;activity.subject=profileDefaults[m.component].subject;activity.pages.forEach(p=>{p.orientation=m.orientation;p.columns=m.columns;});while(activity.pages.length<(m.pageCount||1))activity.pages.push(blankPage(m.orientation,m.columns,'<p><br></p>'));activity.originalLayout=false;activePageId=activity.pages[0].id;if(m.margins)activity.margins={...m.margins};if(typeof m.showPageNumbers==='boolean')activity.showPageNumbers=m.showPageNumbers;if(typeof m.showPersonalLogo==='boolean')activity.showPersonalLogo=m.showPersonalLogo;render();scheduleSave();};
const renderModels=()=>{const customs=getLayoutModels();const all=[...baseModels.map((m,i)=>({id:`base-${i}`,...m,margins:activity.margins,showPageNumbers:true,showPersonalLogo:true})),...customs];const mount=$('modelsList');mount.innerHTML=all.map(m=>`<button class="model-card" data-model="${m.id}"><span>${m.orientation==='landscape'?'▭':'▯'}</span><strong>${escapeHtml(m.name)}</strong><small>${m.pageCount} pág. • ${m.columns} coluna(s)</small></button>`).join('');mount.querySelectorAll<HTMLButtonElement>('[data-model]').forEach(b=>b.addEventListener('click',()=>{const m=all.find(x=>x.id===b.dataset.model);if(!m)return;if(confirm(`Aplicar “${m.name}”?`)){applyLayoutModel(m);closeDialog('modelsDialog');}}));};
const openModels=()=>{renderModels();showDialog('modelsDialog');};
$('saveLayoutModelBtn').addEventListener('click',()=>{const name=prompt('Nome para este modelo de layout:','Meu modelo');if(!name)return;const p=activePage();if(!p)return;const list=getLayoutModels();list.unshift({id:newId(),name,component:activity.component,orientation:p.orientation,columns:p.columns,pageCount:activity.pages.length,margins:{...activity.margins},showPageNumbers:activity.showPageNumbers,showPersonalLogo:activity.showPersonalLogo});dataStorage.setItem(LAYOUT_MODELS_KEY,JSON.stringify(list));void queueAux('model',list[0]);toast('Modelo salvo.');renderModels();});

// Banco de imagens
const saveRemoteImage=async(item:ImageBankItem)=>{try{const r=await fetch('/.netlify/functions/save-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(item)});return r.ok;}catch{return false;}};let imageBankCache:ImageBankItem[]=[];
const mergeRemoteImages=async()=>{const local=getImageBank();if(!navigator.onLine)return local;try{const res=await fetch('/.netlify/functions/list-images');if(!res.ok)return local;const json=await res.json();const remote=Array.isArray(json?.data)?json.data:[];const map=new Map<string,ImageBankItem>();[...remote,...local].forEach((i:any)=>i?.id&&!imageDeleted().includes(i.id)&&map.set(i.id,i));const merged=[...map.values()].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));setImageBank(merged);return merged;}catch{return local;}};
const paintImageBank=()=>{const mount=$('imageBankList');if(!imageBankCache.length){mount.innerHTML='<div class="empty">Banco de imagens vazio.</div>';return;}mount.innerHTML=imageBankCache.map(i=>`<article class="image-card"><img src="${i.dataUrl}" alt="${escapeHtml(i.name)}"><div><strong>${escapeHtml(i.name)}</strong><div class="card-actions"><button data-use-image="${i.id}">Inserir</button><button class="danger" data-delete-image="${i.id}">Excluir</button></div></div></article>`).join('');mount.querySelectorAll<HTMLButtonElement>('[data-use-image]').forEach(b=>b.addEventListener('click',()=>{const i=imageBankCache.find(x=>x.id===b.dataset.useImage);if(i){addFloatingImage(i.dataUrl,i.name);closeDialog('imageBankDialog');}}));mount.querySelectorAll<HTMLButtonElement>('[data-delete-image]').forEach(b=>b.addEventListener('click',async()=>{const id=b.dataset.deleteImage||'';markImageDeleted(id);imageBankCache=imageBankCache.filter(x=>x.id!==id);setImageBank(imageBankCache);paintImageBank();if(navigator.onLine)await flushImages();}));};
$('imageBankBtn').addEventListener('click',async()=>{showDialog('imageBankDialog');imageBankCache=await mergeRemoteImages();paintImageBank();});
$<HTMLInputElement>('imageBankUpload').addEventListener('change',async e=>{const input=e.target as HTMLInputElement;for(const f of [...(input.files||[])].filter(x=>x.type.startsWith('image/'))){const item={id:newId(),name:f.name,dataUrl:await fileToDataUrl(f),createdAt:nowIso()};imageBankCache.unshift(item);markImagePending(item.id,true);if(navigator.onLine)void saveRemoteImage(item).then(ok=>{if(ok)markImagePending(item.id,false);});}try{setImageBank(imageBankCache);}catch{toast('Espaço local cheio; mantenha a página aberta e verifique o backup na nuvem.');}paintImageBank();input.value='';});
$('openGoogleImagesBtn').addEventListener('click',()=>{const q=$<HTMLInputElement>('webImageQuery').value.trim();if(!q){toast('Digite o tema da imagem.');return;}window.open(`https://www.google.com/search?tbm=isch&q=${encodeURIComponent(q)}`,'_blank','noopener,noreferrer');});

// V7 — non-destructive image editing. The displayed raster is regenerated from the original.
const cleanImageAdjustments=():ImageAdjustments=>({left:0,top:0,right:0,bottom:0,rotation:0,brightness:100,contrast:100,gray:false});
let imageSession:{documentId:string;objectId:string;source:HTMLImageElement;settings:ImageAdjustments;lockRatio:boolean;original:string}|null=null;
const imageDecode=(src:string)=>new Promise<HTMLImageElement>((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Não foi possível ler a imagem.'));if(/^https?:/i.test(src))img.crossOrigin='anonymous';img.src=src;});
function drawAdjustedImage(canvas:HTMLCanvasElement,img:HTMLImageElement,a:ImageAdjustments,maxSide:number){const rotated=a.rotation%180!==0;const scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight));const w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale));canvas.width=rotated?h:w;canvas.height=rotated?w:h;const ctx=canvas.getContext('2d')!;ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(a.rotation*Math.PI/180);ctx.filter=`brightness(${a.brightness}%) contrast(${a.contrast}%) grayscale(${a.gray?100:0}%)`;ctx.drawImage(img,-w/2,-h/2,w,h);ctx.setTransform(1,0,0,1,0,0);ctx.filter='none';}
function updateCropBox(){if(!imageSession)return;const a=imageSession.settings;const box=$('cropBox');box.style.left=`${a.left*100}%`;box.style.top=`${a.top*100}%`;box.style.right=`${a.right*100}%`;box.style.bottom=`${a.bottom*100}%`;document.querySelectorAll<HTMLInputElement>('[data-crop-value]').forEach(el=>{const k=el.dataset.cropValue as 'left'|'top'|'right'|'bottom';el.value=String(Math.round(a[k]*100));});}
function refreshImageEdit(){if(!imageSession)return;const a=imageSession.settings;const canvas=$<HTMLCanvasElement>('cropCanvas');drawAdjustedImage(canvas,imageSession.source,a,900);const stage=$('cropStage');stage.style.aspectRatio=`${canvas.width}/${canvas.height}`;stage.style.width=`min(100%, ${Math.min(500,380*canvas.width/canvas.height)}px, ${36*canvas.width/canvas.height}vh)`;$<HTMLInputElement>('imageBrightness').value=String(a.brightness);$<HTMLInputElement>('imageContrast').value=String(a.contrast);$('brightnessValue').textContent=a.brightness+'%';$('contrastValue').textContent=a.contrast+'%';$<HTMLInputElement>('imageGray').checked=a.gray;$<HTMLInputElement>('imageRatio').checked=imageSession.lockRatio;updateCropBox();}
async function openImageEditor(id:string|null){const obj=activity.objects.find(o=>o.id===id&&o.type==='image');if(!obj?.src){toast('Selecione uma imagem inserida na folha.');return;}const documentId=activity.id;const original=obj.originalSrc||obj.src;try{const source=await imageDecode(original);if(activity.id!==documentId||!activity.objects.some(o=>o.id===id))return;imageSession={documentId,objectId:obj.id,source,original,settings:{...cleanImageAdjustments(),...obj.imageAdjustments},lockRatio:obj.lockRatio!==false};showDialog('imageEditDialog');refreshImageEdit();}catch(err){toast(err instanceof Error?err.message:'Imagem inválida.');}}
$('imageAdjustBtn').addEventListener('click',()=>void openImageEditor(selectedObjectId));
$<HTMLDialogElement>('imageEditDialog').addEventListener('close',()=>{imageSession=null;});
function changeCrop(k:'left'|'top'|'right'|'bottom',value:number){if(!imageSession||!Number.isFinite(value))return;const a=imageSession.settings;const opposite={left:'right',right:'left',top:'bottom',bottom:'top'} as const;a[k]=Math.min(.95-a[opposite[k]],Math.max(0,value));updateCropBox();}
document.querySelectorAll<HTMLInputElement>('[data-crop-value]').forEach(el=>el.addEventListener('change',()=>changeCrop(el.dataset.cropValue as 'left'|'top'|'right'|'bottom',Number(el.value)/100)));
document.querySelectorAll<HTMLButtonElement>('[data-crop-handle]').forEach(el=>el.addEventListener('pointerdown',e=>{if(!imageSession)return;e.preventDefault();const h=el.dataset.cropHandle||'';const rect=$('cropStage').getBoundingClientRect();const start={...imageSession.settings};const sx=e.clientX,sy=e.clientY;el.setPointerCapture(e.pointerId);const move=(m:PointerEvent)=>{if(m.pointerId!==e.pointerId||!imageSession)return;const dx=(m.clientX-sx)/rect.width,dy=(m.clientY-sy)/rect.height;if(h.includes('w'))changeCrop('left',start.left+dx);if(h.includes('e'))changeCrop('right',start.right-dx);if(h.includes('n'))changeCrop('top',start.top+dy);if(h.includes('s'))changeCrop('bottom',start.bottom-dy);};const stop=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('lostpointercapture',stop);};el.addEventListener('pointermove',move);el.addEventListener('lostpointercapture',stop);}));
function rotateImage(delta:number){if(!imageSession)return;const a=imageSession.settings;const {left,top,right,bottom}=a;Object.assign(a,delta>0?{left:bottom,top:left,right:top,bottom:right}:{left:top,top:right,right:bottom,bottom:left});a.rotation=(a.rotation+delta+360)%360;refreshImageEdit();}
$('rotateLeft').addEventListener('click',()=>rotateImage(-90));$('rotateRight').addEventListener('click',()=>rotateImage(90));
for(const [id,key] of [['imageBrightness','brightness'],['imageContrast','contrast']] as const){$<HTMLInputElement>(id).addEventListener('input',()=>{if(!imageSession)return;imageSession.settings[key]=Number($<HTMLInputElement>(id).value);refreshImageEdit();});}
$<HTMLInputElement>('imageGray').addEventListener('change',()=>{if(imageSession){imageSession.settings.gray=$<HTMLInputElement>('imageGray').checked;refreshImageEdit();}});
$<HTMLInputElement>('imageRatio').addEventListener('change',()=>{if(imageSession)imageSession.lockRatio=$<HTMLInputElement>('imageRatio').checked;});
$('resetImage').addEventListener('click',()=>{if(imageSession){imageSession.settings=cleanImageAdjustments();refreshImageEdit();}});
$('applyImageEdit').addEventListener('click',()=>{const session=imageSession;if(!session||activity.id!==session.documentId)return;const obj=activity.objects.find(o=>o.id===session.objectId);if(!obj)return;try{const a=session.settings;const source=document.createElement('canvas');drawAdjustedImage(source,session.source,a,2400);const x=Math.round(source.width*a.left),y=Math.round(source.height*a.top),w=Math.max(1,source.width-x-Math.round(source.width*a.right)),h=Math.max(1,source.height-y-Math.round(source.height*a.bottom));const result=document.createElement('canvas');result.width=w;result.height=h;result.getContext('2d')!.drawImage(source,x,y,w,h,0,0,w,h);const unmodified=JSON.stringify(a)===JSON.stringify(cleanImageAdjustments());const src=unmodified?session.original:result.toDataURL('image/png');const p=activity.pages.find(p=>p.id===obj.pageId);if(!p)return;const d=pageDims(p.orientation);const ratio=w/h;const maxWidth=Math.min(d.width-obj.x,(d.height-obj.y)*ratio);const width=Math.min(maxWidth,obj.width);obj.width=width;obj.height=width/ratio;obj.src=src;obj.originalSrc=unmodified?undefined:session.original;obj.imageAdjustments=unmodified?undefined:{...a};obj.lockRatio=session.lockRatio;resizeImageAnchor(obj);selectedObjectId=obj.id;closeDialog('imageEditDialog');renderPages();scheduleSave();toast('Imagem atualizada.');}catch(err){toast('Não foi possível aplicar a edição.');}});

window.addEventListener('beforeunload',()=>{try{if(dirty)saveLocal();}catch{}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&dirty)void persist();});
window.addEventListener('mcs-storage-error',()=>{status.textContent='Falha de gravação local';toast('Não feche a página antes de sincronizar ou exportar um backup.');});


// V8: backup, modelos pedagógicos, conta e filas de sincronização.
const AUX_QUEUE_KEY='marks-class-studio:aux-pending:v8';
const IMAGE_PENDING_KEY='marks-class-studio:images-pending:v8';
const IMAGE_DELETED_KEY='marks-class-studio:images-deleted:v8';
const ACK_DELETE_KEY='marks-class-studio:delete-ack:v8';
const deletionAck=()=>safeJson<string[]>(dataStorage.getItem(ACK_DELETE_KEY),[]);
function acknowledgeDelete(key:string){dataStorage.setItem(ACK_DELETE_KEY,JSON.stringify([...new Set([...deletionAck(),key])]));}
function clearDeleteAck(key:string){dataStorage.setItem(ACK_DELETE_KEY,JSON.stringify(deletionAck().filter(k=>k!==key)));}
// Replay pre-V13 deletions once so the cloud has permanent deletion records.
if(!dataStorage.getItem('mcs-v13-deletion-migration')){dataStorage.setItem(ACK_DELETE_KEY,JSON.stringify(deletionAck().filter(k=>!k.startsWith('activity:'))));dataStorage.setItem('mcs-v13-deletion-migration','1');}
type AuxRecord={kind:'history'|'model'|'prefs';item:any};
const auxPending=()=>safeJson<AuxRecord[]>(dataStorage.getItem(AUX_QUEUE_KEY),[]);
let auxTimer:number|undefined;let auxFlight:Promise<boolean>|null=null;
function queueAux(kind:AuxRecord['kind'],item:any){if(kind==='history')return;try{const list=auxPending().filter(r=>r.kind!==kind||r.item.id!==item.id);list.push({kind,item:structuredClone(item)});dataStorage.setItem(AUX_QUEUE_KEY,compactJson(list));window.clearTimeout(auxTimer);auxTimer=window.setTimeout(()=>void flushAux(),3000);}catch{toast('Dados auxiliares aguardam backup.');}}
async function flushAux():Promise<boolean>{if(auxFlight)return auxFlight;if(!navigator.onLine)return false;const snapshot=auxPending().filter(r=>r.kind!=='history');if(!snapshot.length)return true;auxFlight=(async()=>{let ok=true;const batches:AuxRecord[][]=[];let batch:AuxRecord[]=[],size=0;for(const row of snapshot){const n=compactJson(row).length;if(batch.length&&(batch.length>=8||size+n>2400000)){batches.push(batch);batch=[];size=0;}batch.push(row);size+=n;}if(batch.length)batches.push(batch);for(const rows of batches){try{const res=await fetch('/.netlify/functions/aux-data',{method:'POST',headers:{'Content-Type':'application/json'},body:compactJson({items:rows})});if(!res.ok){ok=false;continue;}const sent=new Map(rows.map(row=>[row.kind+'/'+row.item.id,compactJson(row)]));dataStorage.setItem(AUX_QUEUE_KEY,compactJson(auxPending().filter(r=>sent.get(r.kind+'/'+r.item.id)!==compactJson(r))));}catch{ok=false;}}return ok;})();try{return await auxFlight;}finally{auxFlight=null;}}
const imagePending=()=>safeJson<string[]>(dataStorage.getItem(IMAGE_PENDING_KEY),[]);
function markImagePending(id:string,on:boolean){const ids=new Set(imagePending());on?ids.add(id):ids.delete(id);dataStorage.setItem(IMAGE_PENDING_KEY,JSON.stringify([...ids]));}
const imageDeleted=()=>safeJson<string[]>(dataStorage.getItem(IMAGE_DELETED_KEY),[]);
function markImageDeleted(id:string){clearDeleteAck('image:'+id);dataStorage.setItem(IMAGE_DELETED_KEY,JSON.stringify([...new Set([...imageDeleted(),id])]));markImagePending(id,false);}
let imagesFlight:Promise<boolean>|null=null;
function flushImages(){if(imagesFlight)return imagesFlight;imagesFlight=flushImagesImpl().finally(()=>{imagesFlight=null;});return imagesFlight;}
async function flushImagesImpl(){let ok=true;for(const item of getImageBank().filter(i=>imagePending().includes(i.id))){if(await saveRemoteImage(item))markImagePending(item.id,false);else ok=false;}for(const id of imageDeleted().filter(i=>!deletionAck().includes('image:'+i))){try{const r=await fetch('/.netlify/functions/delete-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(!r.ok)ok=false;else acknowledgeDelete('image:'+id);}catch{ok=false;}}return ok;}
const uniqueById=<T extends {id:string}>(items:T[])=>[...new Map(items.map(i=>[i.id,i])).values()];
async function getCloud<T>(path:string):Promise<T[]>{const r=await fetch('/.netlify/functions/'+path,{cache:'no-store'});if(!r.ok)throw new Error('Não foi possível ler '+path+' ('+r.status+').');const j=await r.json();if(!j.ok||!Array.isArray(j.data))throw new Error('Resposta incompleta de '+path+'.');if(path==='list-activities')rememberDeleted(j.deletedIds);return j.data as T[];}
const prefKeys=['mcs-ruler-hidden','mcs-normalize-import',AUTOSAVE_KEY,FILTER_PREF];
const localPrefs=()=>Object.fromEntries(prefKeys.map(k=>[k,dataStorage.getItem(k)]));
function syncPreferences(){queueAux('prefs',{id:'document-preferences',updatedAt:nowIso(),values:localPrefs()});}
$('toggleRuler').addEventListener('click',syncPreferences);normalizeImport.addEventListener('change',syncPreferences);
function applyPreferences(values:Record<string,unknown>){for(const k of prefKeys){const v=values?.[k];if(k===FILTER_PREF&&typeof v==='string'){try{const a=JSON.parse(v);if(Array.isArray(a)&&a.every(f=>typeof f?.name==='string'&&typeof f?.aliases==='string'))dataStorage.setItem(k,JSON.stringify(a.slice(0,300)));}catch{}}else if(v==='true'||v==='false')dataStorage.setItem(k,v);else if(k===AUTOSAVE_KEY&&[15,30,60,120,180,300,600].includes(Number(v)))dataStorage.setItem(k,String(v));}document.querySelector<HTMLElement>('.ruler-shell')!.hidden=dataStorage.getItem('mcs-ruler-hidden')==='true';normalizeImport.checked=dataStorage.getItem('mcs-normalize-import')!=='false';updateRulerHandles();}
let activitiesFlight:Promise<boolean>|null=null;
function flushActivities(){if(activitiesFlight)return activitiesFlight;activitiesFlight=flushActivitiesImpl().finally(()=>{activitiesFlight=null;});return activitiesFlight;}
async function flushActivitiesImpl(){let ok=true;await remoteQueue;for(const item of getLibrary().filter(i=>pending().includes(i.id))){if(await saveRemote(item)){const latest=getLibrary().find(x=>x.id===item.id);if(!latest||latest.updatedAt<=item.updatedAt)markPending(item.id,false);}else ok=false;}for(const id of deletedIds().filter(i=>!deletionAck().includes('activity:'+i)))try{const r=await fetch('/.netlify/functions/delete-activity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(!r.ok)ok=false;else acknowledgeDelete('activity:'+id);}catch{ok=false;}return ok;}
let startupFlight:Promise<void>|null=null;
function startupSync(){if(startupFlight)return startupFlight;startupFlight=startupSyncImpl().finally(()=>{startupFlight=null;});return startupFlight;}
async function startupSyncImpl(){
 const initial=signature(activity);const initialId=activity.id;const hadLocalDraft=!!dataStorage.getItem(STORAGE_KEY);
 if(!navigator.onLine)return;
 try{const remote=await getCloud<Activity>('list-activities');const remoteMap=new Map(remote.map(i=>[i.id,i]));const local=getLibrary();for(const i of local)if(!remoteMap.has(i.id)&&!deletedIds().includes(i.id)&&pending().includes(i.id))markPending(i.id,true);const merged=uniqueById([...remote.map(normalizeActivity),...local.filter(i=>!remoteMap.has(i.id)||i.updatedAt>=remoteMap.get(i.id)!.updatedAt)]).filter(i=>!deletedIds().includes(i.id)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));setLibrary(merged);
 if(signature(activity)===initial&&activity.id===initialId&&deletedIds().includes(initialId)){activity=blankActivity(activity.component);activePageId=activity.pages[0].id;undoBase=structuredClone(activity);dataStorage.setItem(STORAGE_KEY,compactJson(activity));render();}else if(signature(activity)===initial&&activity.id===initialId&&!pending().includes(initialId)){const next=hadLocalDraft?merged.find(i=>i.id===initialId&&i.updatedAt>activity.updatedAt&&!pending().includes(i.id)):merged.find(i=>i.collection!=='reference');if(next){activity=structuredClone(next);activePageId=activity.pages[0].id;selectedObjectId=null;undoBase=structuredClone(activity);dataStorage.setItem(STORAGE_KEY,compactJson(activity));render();}}
 }catch{status.textContent='Nuvem indisponível • edição local';}
 try{const remote=await getCloud<ImageBankItem>('list-images');const local=getImageBank();const ids=new Set(remote.map(i=>i.id));for(const i of local)if(!ids.has(i.id)&&!imageDeleted().includes(i.id))markImagePending(i.id,true);setImageBank(uniqueById([...remote,...local]).filter(i=>!imageDeleted().includes(i.id)));}catch{}
 try{const rows=await getCloud<AuxRecord>('aux-data');const models=rows.filter(r=>r.kind==='model').map(r=>r.item as LayoutModel);const mids=new Set(models.map(i=>i.id));for(const i of getLayoutModels())if(!mids.has(i.id))queueAux('model',i);dataStorage.setItem(LAYOUT_MODELS_KEY,JSON.stringify(uniqueById([...models,...getLayoutModels()])));const prefs=rows.find(r=>r.kind==='prefs')?.item;if(prefs&&!auxPending().some(r=>r.kind==='prefs'))applyPreferences(prefs.values);}catch{}
 await Promise.all([flushActivities(),flushImages(),flushAux()]);
}
dataStorage.setItem(AUX_QUEUE_KEY,compactJson(auxPending().filter(r=>r.kind!=='history')));
window.addEventListener('online',()=>{void startupSync();});
