$<HTMLSelectElement>('autosaveInterval').addEventListener('change',e=>{dataStorage.setItem(AUTOSAVE_KEY,(e.target as HTMLSelectElement).value);syncPreferences();if(dirty){window.clearTimeout(saveTimer);saveTimer=window.setTimeout(()=>{saveTimer=undefined;void persist();},autosaveSeconds()*1000);}toast('Intervalo de salvamento atualizado.');});
$('cleanLibraryBtn').addEventListener('click',async()=>{const st=$('backupStatus');const button=$<HTMLButtonElement>('cleanLibraryBtn');button.disabled=true;try{if(!navigator.onLine)throw new Error('Conecte-se à internet para limpar também a nuvem.');if(dirty)await persist();await remoteQueue;if(activitiesFlight)await activitiesFlight;const remote=await getCloud<Activity>('list-activities');const docs=newestActivities([...remote.map(normalizeActivity),...getLibrary()]).filter(i=>!deletedIds().includes(i.id));const remove=docs;if(!confirm(`Excluir ${remove.length} atividades antigas de Minhas Atividades e Referências, também na nuvem? O rascunho aberto, o banco de questões e as imagens serão mantidos. Os históricos antigos serão removidos. Exporte um backup antes se quiser guardar cópias.`))return;const ids=new Set(remove.map(i=>i.id));window.clearTimeout(saveTimer);saveTimer=undefined;dirty=false;for(const id of ids){clearDeleteAck('activity:'+id);markPending(id,false);}dataStorage.setItem(deletedKey,JSON.stringify([...new Set([...deletedIds(),...ids])]));setLibrary(docs.filter(i=>!ids.has(i.id)));if(ids.has(activity.id)){const next=structuredClone(activity);next.id=newId();next.libraryName=undefined;next.createdAt=next.updatedAt=nowIso();activity=next;activePageId=next.pages[0].id;selectedObjectId=null;undoStack.length=redoStack.length=0;undoBase=structuredClone(next);dataStorage.setItem(STORAGE_KEY,compactJson(next));render();}setHistory([]);dataStorage.setItem(AUX_QUEUE_KEY,compactJson(auxPending().filter(r=>r.kind!=='history')));await flushStorage();const ok=await flushActivities();let historyOk=false;try{const result=await fetch('/.netlify/functions/aux-data',{method:'DELETE'});historyOk=result.ok;}catch{}libraryCache=getLibrary();st.textContent=ok&&historyOk?`${ids.size} atividades antigas removidas. Rascunho e banco de questões preservados.`:'Limpeza local feita; exclusão de documentos ou históricos na nuvem pendente. Mantenha a conexão e confira novamente.';toast(st.textContent);}catch(err){st.textContent=err instanceof Error?err.message:'Falha na limpeza.';}finally{button.disabled=false;}});
$('passwordBtn').addEventListener('click',()=>{closeDialog('globalSettingsDialog');$<HTMLFormElement>('passwordForm').reset();$('passwordStatus').textContent='';showDialog('passwordDialog');});
$('passwordForm').addEventListener('submit',async e=>{e.preventDefault();const current=$<HTMLInputElement>('currentPassword').value,next=$<HTMLInputElement>('newPassword').value;const st=$('passwordStatus');if(next!==$<HTMLInputElement>('confirmPassword').value){st.textContent='As senhas não coincidem.';return;}const btn=$<HTMLButtonElement>('passwordSubmit');btn.disabled=true;try{await changePassword(current,next);$<HTMLFormElement>('passwordForm').reset();closeDialog('passwordDialog');toast('Senha alterada.');}catch(err){st.textContent=err instanceof Error?err.message:'Não foi possível alterar a senha.';}finally{btn.disabled=false;}});
$('logoutBtn').addEventListener('click',async()=>{if(!confirm('Sair da plataforma?'))return;try{await questionUI.flush();await persist();await Promise.all([flushAux(),flushImages(),flushStorage()]);await signOut();}catch{toast('Não foi possível sair. Confira sua conexão.');}});
// Backup portátil e restauração por mesclagem: nunca apaga registros ausentes no arquivo.
type Backup={format:'marks-class-studio-backup';version:1;createdAt:string;scope:'complete'|'local';draft:Activity;activities:Activity[];images:ImageBankItem[];history:HistoryItem[];models:LayoutModel[];preferences:Record<string,unknown>;memory?:MemoryBackup[];questions?:Question[];curriculum?:ReturnType<typeof curriculumSnapshot>};
function newestActivities(items:Activity[]){const map=new Map<string,Activity>();for(const i of items){if(!map.has(i.id)||map.get(i.id)!.updatedAt<=i.updatedAt)map.set(i.id,i);}return [...map.values()];}
const backupName=()=>`Marks-Class-Studio-Backup-${nowIso().replace(/[:.]/g,'-')}.json`;
async function exportBackup(){const st=$('backupStatus');const btn=$<HTMLButtonElement>('backupExportBtn');btn.disabled=true;try{st.textContent='Reunindo documentos, imagens e arquivos originais…';await questionUI.flush();await persist();await flushStorage();let activities=getLibrary(),images=getImageBank(),history:HistoryItem[]=[],models=getLayoutModels(),scope:Backup['scope']='local';let memory:MemoryBackup[]|undefined;let questions:Question[]|undefined=localQuestions();try{if(!navigator.onLine)throw new Error('Sem internet.');const [a,i,rows]=await Promise.all([getCloud<Activity>('list-activities'),getCloud<ImageBankItem>('list-images'),getCloud<AuxRecord>('aux-data')]);activities=newestActivities([...a.map(normalizeActivity),...activities]).filter(x=>!deletedIds().includes(x.id));images=uniqueById([...i,...images]).filter(x=>!imageDeleted().includes(x.id));models=uniqueById([...rows.filter(r=>r.kind==='model').map(r=>r.item as LayoutModel),...models]);questions=await exportQuestions();memory=await exportMemory();await syncCurriculum();scope='complete';}catch{if(!confirm('Não foi possível consultar toda a nuvem. Exportar backup parcial? Os registros disponíveis localmente serão incluídos, mas os dados da nuvem e os originais antigos podem estar incompletos.')){st.textContent='Backup cancelado. Tente novamente com internet.';return;}}
const backup:Backup={format:'marks-class-studio-backup',version:1,createdAt:nowIso(),scope,draft:structuredClone(activity),activities:newestActivities(activities).filter(i=>!deletedIds().includes(i.id)),images,history,models,preferences:localPrefs(),memory,questions,curriculum:curriculumSnapshot()};const blob=new Blob([compactJson(backup)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=backupName();a.click();window.setTimeout(()=>URL.revokeObjectURL(url),10000);st.textContent=`Backup ${scope==='complete'?'completo':'local'} exportado: ${backup.activities.length} documentos, ${images.length} imagens e ${memory?.length||0} originais e ${questions?.length||0} questões.`;}catch(err){st.textContent=err instanceof Error?err.message:'Não foi possível gerar o backup.';}finally{btn.disabled=false;}}
$('backupExportBtn').addEventListener('click',()=>void exportBackup());$('backupImportBtn').addEventListener('click',()=>$('backupInput').click());
const validId=(id:unknown):id is string=>typeof id==='string'&&/^[\w-]{1,100}$/.test(id);
const safeImage=(s:unknown):string=>typeof s==='string'&&/^data:image\/(?:png|jpeg|jpg|webp|gif|bmp|avif|x-icon|svg\+xml);base64,[a-z0-9+/=\s]+$/i.test(s)?s:'';
function backupHtml(html:string){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set('P DIV SPAN BR STRONG B EM I U S STRIKE OL UL LI H1 H2 H3 H4 H5 H6 BLOCKQUOTE TABLE TBODY THEAD TFOOT TR TD TH COL COLGROUP IMG HR FONT SUP SUB A PRE CODE'.split(' '));for(const el of [...doc.body.querySelectorAll<HTMLElement>('*')]){if(!allowed.has(el.tagName)){if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','LINK','META','FORM'].includes(el.tagName))el.remove();else el.replaceWith(...el.childNodes);continue;}for(const attr of [...el.attributes]){const name=attr.name.toLowerCase();if(!['class','style','colspan','rowspan','span','start','type','width','height','face','size','color','align','alt','src','href','data-original-src','data-q-link'].includes(name)||name==='style'&&/url\s*\(|expression\s*\(|@import/i.test(attr.value)||name==='href'&&!/^https?:\/\//i.test(attr.value)||(name==='src'||name==='data-original-src')&&!safeImage(attr.value)&&!/^https:\/\//i.test(attr.value))el.removeAttribute(attr.name);}if(el.tagName==='IMG'&&!el.hasAttribute('src'))el.remove();}return doc.body.innerHTML;}
function readBackupActivity(raw:any):Activity{if(!raw||!validId(raw.id)||!Array.isArray(raw.pages)||!raw.pages.length||raw.pages.some((p:any)=>!p||!validId(p.id)||typeof p.html!=='string')||!['english','life-project'].includes(raw.component))throw new Error('Atividade inválida no backup.');const a=normalizeActivity(raw);if(!['activity','reference','both'].includes(a.collection||''))a.collection='activity';for(const k of ['top','right','bottom','left'] as const)a.margins[k]=clampMargin(Number(a.margins[k]));for(const field of ['school','teacher','subject','grade','title'] as const)if(typeof a[field]!=='string')throw new Error('Dados de cabeçalho inválidos.');if(a.libraryName!==undefined&&typeof a.libraryName!=='string')throw new Error('Nome inválido.');if(typeof a.updatedAt!=='string'||typeof a.createdAt!=='string')throw new Error('Data inválida.');a.pages.forEach(p=>p.html=backupHtml(p.html));a.answerKeyHtml=backupHtml(a.answerKeyHtml);a.logoDataUrl=safeImage(a.logoDataUrl)||defaultSchoolLogo;a.personalLogoDataUrl=safeImage(a.personalLogoDataUrl);a.objects=a.objects.filter(o=>validId(o.id)&&a.pages.some(p=>p.id===o.pageId)&&['image','textbox'].includes(o.type)).map(o=>({...o,src:safeImage(o.src)||(/^https:\/\//i.test(String(o.src||''))?o.src:''),originalSrc:safeImage(o.originalSrc)||(/^https:\/\//i.test(String(o.originalSrc||''))?o.originalSrc:''),html:backupHtml(typeof o.html==='string'?o.html:''),x:Number(o.x)||0,y:Number(o.y)||0,width:Math.max(1,Number(o.width)||1),height:Math.max(1,Number(o.height)||1),z:Number(o.z)||0}));return a;}
function readBackup(raw:any):Backup{if(!raw||raw.format!=='marks-class-studio-backup'||raw.version!==1||!['local','complete'].includes(raw.scope)||!Array.isArray(raw.activities)||!Array.isArray(raw.images)||!Array.isArray(raw.history)||!Array.isArray(raw.models))throw new Error('Arquivo de backup incompatível.');const draft=readBackupActivity(raw.draft);const activities=raw.activities.map(readBackupActivity);const images:ImageBankItem[]=raw.images.map((i:any)=>{if(!validId(i?.id)||typeof i.name!=='string'||!safeImage(i.dataUrl)||typeof i.createdAt!=='string')throw new Error('Imagem inválida no backup.');return {id:i.id,name:i.name,dataUrl:i.dataUrl,createdAt:i.createdAt};});const history:HistoryItem[]=raw.history.map((i:any)=>{if(!validId(i?.id)||typeof i.savedAt!=='string')throw new Error('Histórico inválido.');return {id:i.id,savedAt:i.savedAt,activity:readBackupActivity(i.activity)};});const models:LayoutModel[]=raw.models.map((m:any)=>{if(!validId(m?.id)||typeof m.name!=='string'||!['english','life-project'].includes(m.component)||!['portrait','landscape'].includes(m.orientation)||![1,2,3].includes(m.columns)||!Number.isInteger(m.pageCount)||m.pageCount<1||m.pageCount>200||!m.margins||!['top','right','bottom','left'].every(k=>typeof m.margins[k]==='number'&&Number.isFinite(m.margins[k])))throw new Error('Modelo inválido no backup.');return m;});return {...raw,draft,activities,images,history,models,preferences:raw.preferences&&typeof raw.preferences==='object'?raw.preferences:{}};}
$<HTMLInputElement>('backupInput').addEventListener('change',async e=>{const input=e.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;const st=$('backupStatus');try{st.textContent='Verificando o backup…';const backup=readBackup(JSON.parse(await file.text()));if(!confirm(`Importar ${backup.activities.length} documentos e ${backup.images.length} imagens? Os registros atuais serão mantidos; em caso de mesmo ID, prevalece a atividade mais recente. Atividades já excluídas não serão recuperadas automaticamente.\n\nExporte um backup antes se desejar guardar uma cópia separada.`)){st.textContent='Restauração cancelada.';return;}await persist();await importMemory(backup.memory);await importQuestions(backup.questions,backupHtml);await restoreCurriculum(backup.curriculum);await mergeRemoteLibrary(getLibrary());await mergeRemoteImages();const docs=newestActivities([...backup.activities,...getLibrary()]).filter(i=>!deletedIds().includes(i.id));const images=uniqueById([...backup.images,...getImageBank()]);const history:HistoryItem[]=[];const models=uniqueById([...backup.models,...getLayoutModels()]);setLibrary(docs);setImageBank(images);setHistory(history);dataStorage.setItem(LAYOUT_MODELS_KEY,JSON.stringify(models));const restoredIds=new Set([...backup.activities,backup.draft].map(i=>i.id));const restoredImageIds=new Set(backup.images.map(i=>i.id));dataStorage.setItem(IMAGE_DELETED_KEY,JSON.stringify(imageDeleted().filter(id=>!restoredImageIds.has(id))));for(const i of docs.filter(i=>restoredIds.has(i.id)))markPending(i.id,true);for(const i of images.filter(i=>restoredImageIds.has(i.id)))markImagePending(i.id,true);for(const i of backup.models)queueAux('model',i);applyPreferences(backup.preferences);syncPreferences();activity=structuredClone(docs.find(i=>i.id===backup.draft.id)||backup.draft);if(deletedIds().includes(activity.id)){activity.id=newId();activity.libraryName=undefined;}activePageId=activity.pages[0].id;selectedObjectId=null;undoBase=structuredClone(activity);undoStack.length=redoStack.length=0;render();await persist();const results=await Promise.all([flushActivities(),flushImages(),flushAux(),flushStorage()]);st.textContent=results.every(Boolean)?'Backup restaurado e sincronizado.':'Backup restaurado neste dispositivo. Sincronização pendente; mantenha uma cópia do arquivo.';toast(st.textContent);}catch(err){st.textContent=err instanceof Error?err.message:'Não foi possível restaurar o backup.';} });
function borderFormValue():PageBorder|undefined{return $<HTMLInputElement>('pageBorderEnabled').checked?normalizeBorder({width:$<HTMLInputElement>('pageBorderWidth').value,style:$<HTMLSelectElement>('pageBorderStyle').value,color:$<HTMLInputElement>('pageBorderColor').value,gap:$<HTMLInputElement>('pageBorderGap').value}):undefined;}
function paintBorderSample(){const b=borderFormValue();const sample=$('pageBorderSample').firstElementChild as HTMLElement;sample.style.border=b?`${b.width}pt ${b.style} ${b.color}`:'0';sample.style.inset=`${b?Math.max(6,15-b.gap):10}px`;}
$('pageBorderBtn').addEventListener('click',()=>{const b=activePage().border;$<HTMLInputElement>('pageBorderEnabled').checked=!!b;$<HTMLInputElement>('pageBorderWidth').value=String(b?.width??1);$<HTMLSelectElement>('pageBorderStyle').value=b?.style??'solid';$<HTMLInputElement>('pageBorderColor').value=b?.color??'#222222';$<HTMLInputElement>('pageBorderGap').value=String(b?.gap??2);$<HTMLSelectElement>('pageBorderScope').value='all';paintBorderSample();showDialog('pageBorderDialog');});
$('pageBorderForm').addEventListener('input',paintBorderSample);
$('pageBorderForm').addEventListener('submit',e=>{e.preventDefault();const b=borderFormValue();const pages=$<HTMLSelectElement>('pageBorderScope').value==='all'?activity.pages:[activePage()];for(const p of pages)p.border=b?{...b}:undefined;renderPages();scheduleSave();closeDialog('pageBorderDialog');toast(b?'Borda aplicada.':'Borda removida.');});
